SOURCE_HASH='7ce58c244f1de1f334df83994d112d66de8b25a9b97bd735c25303d4870db809'
ASSET_HASH='ded2083c88cc39bc860d4f66ac4d8db8489e867fbc4c87ff4d4a02bc968500c1'
DATA=''
from pathlib import Path
import base64,hashlib,datetime,shutil,os
root=Path('/var/www/azmednsk-preview')
p=root/'osteopaty/index.html'
a=root/'assets/osteopaty-collage-fast-20261114.webp'
old='/assets/osteopaty-collage-20261113.png'
new='/assets/osteopaty-collage-fast-20261114.webp'
sha=lambda b:hashlib.sha256(b).hexdigest()
source=root/old.lstrip('/')
assert sha(source.read_bytes())==SOURCE_HASH,'STOP: collage changed'
before=p.read_bytes()
s=before.decode()
assert s.count(old)>=1,'STOP: source reference missing'
assert s.count('<img src="'+old+'"')==1,'STOP: collage tag mismatch'
after=s.replace(old,new).encode()
blob=base64.b64decode(DATA)
assert sha(blob)==ASSET_HASH,'STOP: asset checksum'
assert not a.exists() or a.read_bytes()==blob,'STOP: asset conflict'
backup=Path('/var/backups/azmednsk')/('collage-webp-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
backup.mkdir(parents=True)
shutil.copy2(p,backup/'index.html')
assert p.read_bytes()==before,'STOP: concurrent modification'
a.write_bytes(blob);a.chmod(0o644)
tmp=p.with_name('index.html.collage-tmp')
tmp.write_bytes(after);shutil.copystat(p,tmp);os.replace(tmp,p)
assert p.read_bytes()==after and sha(a.read_bytes())==ASSET_HASH
assert sha(source.read_bytes())==SOURCE_HASH
print('COLLAGE_WEBP=PASS; DIMENSIONS=2048x682; ORIGINAL=UNCHANGED')
print('BYTES=2698935 -> '+str(len(blob)))
print('BACKUP='+str(backup))
print('URL=https://azmednsk.ru/osteopaty/')
